// badgraph -- a small tree / DAG library with topological sort and a few
// graph algorithms.  Used as a benchmark corpus.
#pragma once

#include <cstdint>
#include <map>
#include <set>
#include <string>
#include <vector>

namespace badgraph {

struct Node {
    int id = 0;
    std::string label;
    double weight = 0.0;
    int depth = 0;
    Node* parent = nullptr;
    std::vector<Node*> children;
    std::vector<int> tags;
};

class Graph {
public:
    Graph() = default;
    ~Graph();

    Node* addNode(std::string label, double weight);
    void addEdge(int from, int to);
    void removeEdge(int from, int to);
    void removeNode(int id);

    Node* node(int id) const;
    std::size_t size() const { return nodes_.size(); }
    std::vector<int> ids() const;
    const std::vector<int>& neighbors(int id) const;

    std::map<int, int> indegrees() const;
    int indegreeOf(int id) const;

    Graph* clone() const;
    void compact();
    void recomputeDepths();
    double totalWeight() const;

    const std::map<int, Node*>& nodeMap() const { return nodes_; }
    const std::map<int, std::vector<int>>& adjacency() const { return adj_; }

private:
    std::map<int, Node*> nodes_;
    std::map<int, std::vector<int>> adj_;
    mutable std::map<int, int> indegCache_;
    int nextId_ = 0;
};

// ---- generators -----------------------------------------------------------
Graph* makeRandomTree(int n, uint64_t seed);
Graph* makeRandomDag(int n, int extraEdges, uint64_t seed);
Graph* makeDeepChainTree(int n, int branch, uint64_t seed);

// ---- topological sort -----------------------------------------------------
std::vector<int> topoSortNaive(const Graph& g);
std::vector<int> topoSortKahnSlow(const Graph& g);
std::vector<int> topoSortDfsRecursive(const Graph& g);
bool hasCycle(const Graph& g);

// ---- algorithms -----------------------------------------------------------
int lcaNaive(const Graph& g, int a, int b);
double subtreeSum(const Graph& g, int root);
std::vector<double> subtreeSumAll(const Graph& g);
std::vector<double> longestPathDag(const Graph& g, const std::vector<int>& order);
double criticalPath(const Graph& g);
std::vector<int> bfsLevels(const Graph& g, int root);
std::vector<int> buildCsrAndCount(const Graph& g);
std::string describeHot(const Graph& g, int limit);

// ---- helpers --------------------------------------------------------------
uint64_t checksum(const std::vector<int>& v);
uint64_t checksum(const std::vector<double>& v);
uint64_t checksum(const std::string& s);
bool isValidTopoOrder(const Graph& g, const std::vector<int>& order);

struct Lcg {
    uint64_t s;
    explicit Lcg(uint64_t seed) : s(seed ? seed : 1) {}
    uint64_t next() { s = s * 6364136223846793005ULL + 1442695040888963407ULL; return s >> 17; }
    int below(int n) { return n <= 0 ? 0 : (int)(next() % (uint64_t)n); }
    double unit() { return (double)(next() % 100000u) / 100000.0; }
};

}  // namespace badgraph
