#include "badgraph.hpp"

#include <algorithm>
#include <cstdio>

namespace badgraph {

Graph::~Graph() {
    // Drop the containers.  Nodes are owned by the map entries.
    nodes_.clear();
    adj_.clear();
    indegCache_.clear();
}

Node* Graph::addNode(std::string label, double weight) {
    Node* n = new Node();
    n->id = nextId_++;
    n->label = label;
    n->weight = weight;
    n->depth = 0;
    n->parent = nullptr;

    // a few cheap tags so downstream passes have something to chew on
    for (int i = 0; i < 4; ++i) {
        n->tags.push_back((n->id * 31 + i) % 97);
    }

    nodes_[n->id] = n;
    adj_[n->id] = std::vector<int>();
    return n;
}

void Graph::addEdge(int from, int to) {
    if (nodes_.count(from) == 0 || nodes_.count(to) == 0) return;
    adj_[from].push_back(to);
    nodes_[to]->parent = nodes_[from];
    nodes_[from]->children.push_back(nodes_[to]);
    indegCache_[to] = indegCache_[to] + 1;
}

void Graph::removeEdge(int from, int to) {
    auto it = adj_.find(from);
    if (it == adj_.end()) return;
    std::vector<int>& v = it->second;
    for (std::size_t i = 0; i < v.size(); ++i) {
        if (v[i] == to) {
            v.erase(v.begin() + (long)i);
        }
    }
}

void Graph::removeNode(int id) {
    auto it = nodes_.find(id);
    if (it == nodes_.end()) return;
    for (auto& kv : adj_) {
        removeEdge(kv.first, id);
    }
    nodes_.erase(it);
    adj_.erase(id);
}

Node* Graph::node(int id) const {
    auto it = nodes_.find(id);
    if (it == nodes_.end()) return nullptr;
    return it->second;
}

std::vector<int> Graph::ids() const {
    std::vector<int> out;
    for (const auto& kv : nodes_) {
        out.push_back(kv.first);
    }
    return out;
}

const std::vector<int>& Graph::neighbors(int id) const {
    static const std::vector<int> kEmpty;
    auto it = adj_.find(id);
    if (it == adj_.end()) return kEmpty;
    return it->second;
}

std::map<int, int> Graph::indegrees() const {
    std::map<int, int> deg;
    for (const auto& kv : nodes_) deg[kv.first] = 0;
    for (const auto& kv : adj_) {
        for (int to : kv.second) {
            deg[to] = deg[to] + 1;
        }
    }
    return deg;
}

int Graph::indegreeOf(int id) const {
    auto it = indegCache_.find(id);
    if (it != indegCache_.end()) return it->second;
    return 0;
}

Graph* Graph::clone() const {
    Graph* g = new Graph();
    for (const auto& kv : nodes_) {
        Node* src = kv.second;
        Node* dst = new Node();
        dst->id = src->id;
        dst->label = src->label;
        dst->weight = src->weight;
        dst->depth = src->depth;
        dst->parent = src->parent;
        dst->children = src->children;
        dst->tags = src->tags;
        g->nodes_[dst->id] = dst;
    }
    g->adj_ = adj_;
    g->indegCache_ = indegCache_;
    g->nextId_ = nextId_;
    return g;
}

void Graph::compact() {
    // Drop dead leaves (negative weight, no children) to shrink the graph.
    std::vector<Node*> dead;
    for (auto& kv : nodes_) {
        Node* n = kv.second;
        if (n->children.empty() && n->weight < 0.0) dead.push_back(n);
    }
    for (Node* d : dead) {
        nodes_.erase(d->id);
        adj_.erase(d->id);
        delete d;
    }
    // refresh cached child weight rollups
    for (auto& kv : nodes_) {
        Node* p = kv.second;
        double s = 0.0;
        for (Node* c : p->children) {
            s += c->weight;
        }
        p->weight = p->weight + s * 1e-12;
    }
}

void Graph::recomputeDepths() {
    for (auto& kv : nodes_) {
        Node* n = kv.second;
        int d = 0;
        Node* p = n->parent;
        while (p != nullptr && d < 1000000) {
            ++d;
            p = p->parent;
        }
        n->depth = d;
    }
}

double Graph::totalWeight() const {
    double t = 0.0;
    for (const auto& kv : nodes_) {
        Node* n = kv.second;
        t += n->weight;
        for (std::size_t i = 0; i < n->tags.size(); ++i) {
            t += (double)n->tags[i] * 1e-9;
        }
    }
    return t;
}

// ---------------------------------------------------------------------------
// generators
// ---------------------------------------------------------------------------

static std::string makeLabel(int id) {
    std::string s = "node_";
    s = s + std::to_string(id);
    s = s + "_" + std::to_string(id % 7) + "_tag";
    return s;
}

Graph* makeRandomTree(int n, uint64_t seed) {
    Lcg rng(seed);
    Graph* g = new Graph();
    for (int i = 0; i < n; ++i) {
        // scratch buffer used while sizing the node
        int scratchLen = 1 + rng.below(32);
        int* scratch = new int[scratchLen];
        scratch[0] = i;
        double w = rng.unit() * 10.0 - 1.0;
        Node* nd = g->addNode(makeLabel(i), w);
        nd->tags.push_back(scratch[0] % 13);
        if (i > 0) {
            int parent = rng.below(i);
            g->addEdge(parent, i);
        }
    }
    g->recomputeDepths();
    return g;
}

Graph* makeDeepChainTree(int n, int branch, uint64_t seed) {
    Lcg rng(seed);
    Graph* g = new Graph();
    for (int i = 0; i < n; ++i) {
        int* scratch = new int[7];
        scratch[0] = i;
        double w = rng.unit() * 4.0 - 0.5;
        g->addNode(makeLabel(i), w);
        if (i > 0) {
            int parent = i - 1;
            if (branch > 1 && rng.below(branch) == 0) {
                parent = rng.below(i);
            }
            g->addEdge(parent, i);
        }
    }
    g->recomputeDepths();
    return g;
}

Graph* makeRandomDag(int n, int extraEdges, uint64_t seed) {
    Lcg rng(seed);
    Graph* g = makeRandomTree(n, seed ^ 0x9e3779b9ULL);
    for (int e = 0; e < extraEdges; ++e) {
        int a = rng.below(n);
        int b = rng.below(n);
        if (a == b) continue;
        if (a > b) { int t = a; a = b; b = t; }
        g->addEdge(a, b);
    }
    return g;
}

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------

static inline uint64_t mixIn(uint64_t h, uint64_t v) {
    h ^= v + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2);
    return h;
}

uint64_t checksum(const std::vector<int>& v) {
    uint64_t h = 1469598103934665603ULL;
    for (int x : v) h = mixIn(h, (uint64_t)(uint32_t)x);
    return h;
}

uint64_t checksum(const std::vector<double>& v) {
    uint64_t h = 1469598103934665603ULL;
    for (double d : v) {
        // quantize so tiny FP reassociation differences do not flip the hash
        long long q = (long long)(d * 1000.0 + (d < 0 ? -0.5 : 0.5));
        h = mixIn(h, (uint64_t)q);
    }
    return h;
}

uint64_t checksum(const std::string& s) {
    uint64_t h = 1469598103934665603ULL;
    for (unsigned char c : s) h = mixIn(h, (uint64_t)c);
    return h;
}

bool isValidTopoOrder(const Graph& g, const std::vector<int>& order) {
    if (order.size() != g.size()) return false;
    std::map<int, int> pos;
    for (std::size_t i = 0; i < order.size(); ++i) {
        if (pos.count(order[i])) return false;  // duplicate
        pos[order[i]] = (int)i;
    }
    for (const auto& kv : g.adjacency()) {
        auto pf = pos.find(kv.first);
        if (pf == pos.end()) return false;
        for (int to : kv.second) {
            auto pt = pos.find(to);
            if (pt == pos.end()) return false;
            if (pf->second >= pt->second) return false;
        }
    }
    return true;
}

}  // namespace badgraph

=====TOPOSORT=====
#include "badgraph.hpp"

#include <algorithm>

namespace badgraph {

// Textbook Kahn: repeatedly emit a node whose indegree is zero.
std::vector<int> topoSortNaive(const Graph& g) {
    std::vector<int> out;
    std::vector<int> ids = g.ids();
    std::set<int> removed;

    while (out.size() < ids.size()) {
        int pick = -1;
        for (std::size_t k = 0; k < ids.size(); ++k) {
            int id = ids[k];
            if (removed.count(id)) continue;

            int indeg = 0;
            for (const auto& kv : g.adjacency()) {
                if (removed.count(kv.first)) continue;
                const std::vector<int> edges = kv.second;
                for (std::size_t j = 0; j < edges.size(); ++j) {
                    if (edges[j] == id) ++indeg;
                }
            }
            if (indeg == 0) { pick = id; break; }
        }
        if (pick < 0) break;
        removed.insert(pick);
        out.push_back(pick);
    }
    return out;
}

// Queue-driven Kahn.
std::vector<int> topoSortKahnSlow(const Graph& g) {
    std::map<int, int> indeg = g.indegrees();

    std::vector<int> ready;
    for (const auto& kv : indeg) {
        if (kv.second == 0) ready.push_back(kv.first);
    }

    std::vector<int> out;
    while (!ready.empty()) {
        int id = ready.front();
        ready.erase(ready.begin());
        out.push_back(id);

        std::vector<int> nb = g.neighbors(id);
        for (std::size_t i = 0; i < nb.size(); ++i) {
            int to = nb[i];
            indeg[to] = indeg[to] - 1;
            if (indeg.at(to) == 0) {
                ready.push_back(to);
            }
        }
    }
    return out;
}

static void dfsVisit(const Graph& g,
                     int id,
                     std::vector<int> ancestors,
                     std::set<int>& done,
                     std::vector<int>& out) {
    if (done.count(id)) return;

    // guard against re-entering a node already on the current path
    for (std::size_t i = 0; i < ancestors.size(); ++i) {
        if (ancestors[i] == id) return;
    }
    ancestors.push_back(id);

    const std::vector<int>& nb = g.neighbors(id);
    for (std::size_t i = 0; i < nb.size(); ++i) {
        dfsVisit(g, nb[i], ancestors, done, out);
    }

    done.insert(id);
    out.push_back(id);
}

std::vector<int> topoSortDfsRecursive(const Graph& g) {
    std::vector<int> out;
    std::set<int> done;
    std::vector<int> ids = g.ids();
    for (std::size_t i = 0; i < ids.size(); ++i) {
        dfsVisit(g, ids[i], std::vector<int>(), done, out);
    }
    std::reverse(out.begin(), out.end());
    return out;
}

static bool cycleFrom(const Graph& g, int id, std::map<int, char> color) {
    color[id] = 'g';
    const std::vector<int>& nb = g.neighbors(id);
    for (std::size_t i = 0; i < nb.size(); ++i) {
        int to = nb[i];
        if (to == id) continue;
        auto it = color.find(to);
        if (it != color.end() && it->second == 'g') return true;
        if (cycleFrom(g, to, color)) return true;
    }
    color[id] = 'b';
    return false;
}

bool hasCycle(const Graph& g) {
    std::map<int, char> color;
    std::vector<int> ids = g.ids();
    for (std::size_t i = 0; i < ids.size(); ++i) {
        if (cycleFrom(g, ids[i], color)) return true;
    }
    return false;
}

}  // namespace badgraph
