#include "badgraph.hpp"

#include <algorithm>
#include <cmath>

namespace badgraph {

int lcaNaive(const Graph& g, int a, int b) {
    Node* x = g.node(a);
    Node* y = g.node(b);
    if (x == nullptr || y == nullptr) return -1;

    std::vector<int> pathA;
    while (x != nullptr) {
        pathA.push_back(x->id);
        x = x->parent;
    }

    while (y != nullptr) {
        for (std::size_t i = 0; i < pathA.size(); ++i) {
            if (pathA[i] == y->id) return y->id;
        }
        y = y->parent;
    }
    return -1;
}

double subtreeSum(const Graph& g, int root) {
    Node* n = g.node(root);
    if (n == nullptr) return 0.0;

    double sum = n->weight;
    const std::vector<int>& kids = g.neighbors(root);
    for (std::size_t i = 0; i < kids.size(); ++i) {
        Node* c = g.node(kids[i]);
        if (c == nullptr) continue;
        sum += subtreeSum(g, c->id);
    }
    return sum;
}

std::vector<double> subtreeSumAll(const Graph& g) {
    std::vector<double> out;
    std::vector<int> ids = g.ids();
    for (std::size_t i = 0; i < ids.size(); ++i) {
        out.push_back(subtreeSum(g, ids[i]));
    }
    return out;
}

std::vector<double> longestPathDag(const Graph& g, const std::vector<int>& order) {
    std::map<int, double> dist;
    for (const auto& kv : g.nodeMap()) {
        dist[kv.first] = kv.second->weight;
    }

    for (std::size_t i = 0; i < order.size(); ++i) {
        int id = order[i];
        std::vector<int> nb = g.neighbors(id);
        for (std::size_t j = 0; j < nb.size(); ++j) {
            int to = nb[j];
            Node* tn = g.node(to);
            if (tn == nullptr) continue;
            double cand = dist[id] + tn->weight;
            if (cand > dist[to]) {
                dist[to] = cand;
            }
        }
    }

    std::vector<double> out;
    for (const auto& kv : g.nodeMap()) {
        out.push_back(dist[kv.first]);
    }
    return out;
}

double criticalPath(const Graph& g) {
    std::vector<int> order = topoSortKahnSlow(g);
    std::vector<double> dist = longestPathDag(g, order);
    double best = 0.0;
    for (std::size_t i = 0; i < dist.size(); ++i) {
        if (dist[i] > best) best = dist[i];
    }
    return best;
}

std::vector<int> bfsLevels(const Graph& g, int root) {
    std::map<int, int> level;
    std::vector<int> frontier;
    frontier.push_back(root);
    level[root] = 0;

    while (!frontier.empty()) {
        int id = frontier.front();
        frontier.erase(frontier.begin());

        std::vector<int> nb = g.neighbors(id);
        for (std::size_t i = 0; i < nb.size(); ++i) {
            int to = nb[i];
            if (level.count(to) == 0) {
                level[to] = level[id] + 1;
                frontier.push_back(to);
            }
        }
    }

    std::vector<int> out;
    for (const auto& kv : g.nodeMap()) {
        if (level.count(kv.first)) {
            out.push_back(level[kv.first]);
        } else {
            out.push_back(-1);
        }
    }
    return out;
}

// Flatten the adjacency map into CSR form and return the per-node out-degree.
std::vector<int> buildCsrAndCount(const Graph& g) {
    int n = (int)g.size();
    if (n <= 0) return std::vector<int>();

    int* rowStart = new int[n];
    int* degree = new int[n];

    int i = 0;
    for (const auto& kv : g.adjacency()) {
        degree[i] = (int)kv.second.size();
        ++i;
    }

    rowStart[0] = 0;
    for (int k = 1; k <= n; ++k) {
        rowStart[k] = rowStart[k - 1] + degree[k - 1];
    }

    int total = rowStart[n];
    int* colIndex = new int[total > 0 ? total : 1];

    i = 0;
    int w = 0;
    for (const auto& kv : g.adjacency()) {
        for (std::size_t j = 0; j < kv.second.size(); ++j) {
            colIndex[w++] = kv.second[j];
        }
        ++i;
    }

    std::vector<int> out;
    for (int k = 0; k < n; ++k) out.push_back(degree[k]);

    delete[] rowStart;
    delete[] degree;
    return out;
}

static std::string upperFirst(std::string s) {
    if (!s.empty() && s[0] >= 'a' && s[0] <= 'z') s[0] = (char)(s[0] - 32);
    return s;
}

static bool labelMatches(std::string label, std::string needle) {
    return label.find(needle) != std::string::npos;
}

std::string describeHot(const Graph& g, int limit) {
    std::string report = "";
    int count = 0;
    for (const auto& kv : g.nodeMap()) {
        if (count >= limit) break;
        Node* n = kv.second;
        if (!labelMatches(n->label, "node_")) continue;

        std::string line = upperFirst(n->label);
        line = line + " d=" + std::to_string(n->depth);
        line = line + " w=" + std::to_string((long long)(n->weight * 100));
        line = line + " k=" + std::to_string((long long)n->children.size());
        for (std::size_t t = 0; t < n->tags.size(); ++t) {
            line = line + ":" + std::to_string(n->tags[t]);
        }
        report = report + line + "\n";
        ++count;
    }
    return report;
}

}  // namespace badgraph

// Benchmark driver for badgraph.
//
//   ./bin/bench                 run everything at scale 1.0
//   ./bin/bench --scale 0.25    smaller workload (fast smoke)
//   ./bin/bench --reps 5        repetitions per benchmark (the fastest wins)
//   ./bin/bench --only topo     run benchmarks whose name contains "topo"
//   ./bin/bench --json out.json write machine readable results
//
// Each benchmark is timed `reps` times and the *minimum* is reported, which is
// far more stable than a single sample.  Each one also prints a checksum over
// its real output; an optimization is only valid if the checksum is unchanged.
#include "badgraph.hpp"

#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

using namespace badgraph;

namespace {

struct Result {
    std::string name;
    double ms = 0.0;
    uint64_t sum = 0;
    std::string note;
};

std::vector<Result> g_results;
const char* g_only = nullptr;
int g_reps = 3;

double nowMs() {
    using clock = std::chrono::steady_clock;
    static clock::time_point origin = clock::now();
    return std::chrono::duration<double, std::milli>(clock::now() - origin).count();
}

int scaled(int base, double s) {
    int v = (int)(base * s);
    return v < 4 ? 4 : v;
}

bool wanted(const std::string& name) {
    if (g_only == nullptr) return true;
    return name.find(g_only) != std::string::npos;
}

// fn(note) runs one iteration and returns a checksum of its output.
template <class F>
void bench(const char* name, F fn) {
    if (!wanted(name)) return;

    double best = -1.0;
    uint64_t sum = 0;
    std::string note;
    bool stable = true;

    for (int r = 0; r < g_reps; ++r) {
        std::string thisNote;
        double t0 = nowMs();
        uint64_t s = fn(thisNote);
        double dt = nowMs() - t0;
        if (r == 0) {
            sum = s;
            note = thisNote;
        } else if (s != sum) {
            stable = false;
        }
        if (best < 0.0 || dt < best) best = dt;
    }
    if (!stable) note += " NONDETERMINISTIC";

    Result res;
    res.name = name;
    res.ms = best;
    res.sum = sum;
    res.note = note;
    g_results.push_back(res);
    std::printf("  %-22s %10.2f ms   sum=0x%016llx  %s\n",
                name, best, (unsigned long long)sum, note.c_str());
    std::fflush(stdout);
}

}  // namespace

int main(int argc, char** argv) {
    double scale = 1.0;
    const char* jsonPath = "bench_results.json";

    for (int i = 1; i < argc; ++i) {
        if (std::strcmp(argv[i], "--scale") == 0 && i + 1 < argc) {
            scale = std::atof(argv[++i]);
        } else if (std::strcmp(argv[i], "--reps") == 0 && i + 1 < argc) {
            g_reps = std::atoi(argv[++i]);
        } else if (std::strcmp(argv[i], "--only") == 0 && i + 1 < argc) {
            g_only = argv[++i];
        } else if (std::strcmp(argv[i], "--json") == 0 && i + 1 < argc) {
            jsonPath = argv[++i];
