static std::map<int, int> refIndegrees(const Graph& g) {
    std::map<int, int> deg;
    for (const auto& kv : g.nodeMap()) deg[kv.first] = 0;
    for (const auto& kv : g.adjacency())
        for (int to : kv.second) deg[to] += 1;
    return deg;
}

static std::vector<int> refTopo(const Graph& g) {
    std::map<int, int> deg = refIndegrees(g);
    std::deque<int> q;
    for (const auto& kv : deg)
        if (kv.second == 0) q.push_back(kv.first);
    std::vector<int> out;
    while (!q.empty()) {
        int id = q.front();
        q.pop_front();
        out.push_back(id);
        for (int to : g.neighbors(id))
            if (--deg[to] == 0) q.push_back(to);
    }
    return out;
}

static std::map<int, int> refDepths(const Graph& g, int root) {
    std::map<int, int> d;
    std::deque<int> q;
    d[root] = 0;
    q.push_back(root);
    while (!q.empty()) {
        int id = q.front();
        q.pop_front();
        for (int to : g.neighbors(id)) {
            if (!d.count(to)) {
                d[to] = d[id] + 1;
                q.push_back(to);
            }
        }
    }
    return d;
}

// LCA on a rooted tree via ancestor chains rebuilt from the adjacency map.
static int refLca(const Graph& g, int root, int a, int b) {
    std::map<int, int> up;
    std::deque<int> q;
    up[root] = -1;
    q.push_back(root);
    while (!q.empty()) {
        int id = q.front();
        q.pop_front();
        for (int to : g.neighbors(id)) {
            if (!up.count(to)) {
                up[to] = id;
                q.push_back(to);
            }
        }
    }
    std::set<int> anc;
    for (int x = a; x != -1; x = up.count(x) ? up[x] : -1) {
        anc.insert(x);
        if (x == root) break;
    }
    for (int y = b; y != -1; y = up.count(y) ? up[y] : -1) {
        if (anc.count(y)) return y;
        if (y == root) break;
    }
    return -1;
}

static double refSubtreeSum(const Graph& g, int root) {
    double total = 0.0;
    std::vector<int> stack;
    std::set<int> seen;
    stack.push_back(root);
    while (!stack.empty()) {
        int id = stack.back();
        stack.pop_back();
        if (seen.count(id)) continue;
        seen.insert(id);
