#!/usr/bin/env bash
# One command to build, gate on correctness, and benchmark badgraph.
#
#   ./run.sh              build + tests + bench (+ compare against baseline)
#   ./run.sh quick        same, at 1/4 workload
#   ./run.sh baseline     record the current numbers as baseline.json
set -u
cd "$(dirname "$0")"

MODE="${1:-check}"
SCALE="1.0"
[ "$MODE" = "quick" ] && SCALE="0.25"

hr() { printf '=%.0s' $(seq 1 74); echo; }
step() { hr; echo "== $1"; hr; }

fail=0

build() {
    step "build"
    make -s all || { echo "BUILD FAILED"; exit 2; }
    echo "ok"
}

run_tests() {
    step "correctness gate"
    if ./bin/tests; then
        echo "tests: PASS"
    else
        echo "tests: FAIL  (benchmark numbers below are meaningless until this is green)"
        fail=1
    fi
}

run_bench() {
    step "benchmark (scale=$SCALE)"
    ./bin/bench --scale "$SCALE" --json bench_results.json || fail=1
}

run_compare() {
    if [ -f baseline.json ]; then
        bscale=$(python3 -c 'import json,sys; print("%.4f" % json.load(open("baseline.json"))["scale"])' 2>/dev/null || echo "")
        cscale=$(python3 -c "print('%.4f' % $SCALE)")
        if [ -n "$bscale" ] && [ "$bscale" != "$cscale" ]; then
            echo
            echo "baseline.json was recorded at scale $bscale, this run used $cscale -- skipping the comparison."
            echo "re-run with the same scale, or record a new baseline."
            return
        fi
        step "vs baseline"
        python3 tools/compare.py baseline.json bench_results.json || fail=1
    else
        echo
        echo "no baseline.json yet -- run './run.sh baseline' to record one."
    fi
}

case "$MODE" in
    check|quick)
        build; run_tests; run_bench; run_compare ;;
    baseline)
        build; run_tests; ./bin/bench --scale "$SCALE" --json baseline.json
        echo "baseline written to baseline.json" ;;
    bench)
        build; run_bench ;;
    *)
        echo "usage: ./run.sh [check|quick|bench|baseline]"; exit 2 ;;
esac

hr
if [ "$fail" -eq 0 ]; then echo "RESULT: ok"; else echo "RESULT: problems found (see above)"; fi
exit "$fail"
