     7	// Textbook Kahn: repeatedly emit a node whose indegree is zero.
     8	std::vector<int> topoSortNaive(const Graph& g) {
     9	    std::vector<int> out;
    10	    std::vector<int> ids = g.ids();
    11	    std::set<int> removed;
    12	
    13	    while (out.size() < ids.size()) {
    14	        int pick = -1;
    15	        for (std::size_t k = 0; k < ids.size(); ++k) {
    16	            int id = ids[k];
    17	            if (removed.count(id)) continue;
    18	
    19	            int indeg = 0;
    20	            for (const auto& kv : g.adjacency()) {
    21	                if (removed.count(kv.first)) continue;
    22	                const std::vector<int> edges = kv.second;
    23	                for (std::size_t j = 0; j < edges.size(); ++j) {
    24	                    if (edges[j] == id) ++indeg;
    25	                }
    26	            }
    27	            if (indeg == 0) { pick = id; break; }
    28	        }
    29	        if (pick < 0) break;
    30	        removed.insert(pick);
    31	        out.push_back(pick);
    32	    }
    33	    return out;
    34	}
    35	
    36	// Queue-driven Kahn.
    37	std::vector<int> topoSortKahnSlow(const Graph& g) {
    38	    std::map<int, int> indeg = g.indegrees();
    39	
    40	    std::vector<int> ready;
    41	    for (const auto& kv : indeg) {
    42	        if (kv.second == 0) ready.push_back(kv.first);
    43	    }
    44	
    45	    std::vector<int> out;
    46	    while (!ready.empty()) {
    47	        int id = ready.front();
    48	        ready.erase(ready.begin());
    49	        out.push_back(id);
    50	
    51	        std::vector<int> nb = g.neighbors(id);
    52	        for (std::size_t i = 0; i < nb.size(); ++i) {
    53	            int to = nb[i];
    54	            indeg[to] = indeg[to] - 1;
    55	            if (indeg.at(to) == 0) {
    56	                ready.push_back(to);
    57	            }
    58	        }
    59	    }
    60	    return out;
    61	}
    62	
    63	static void dfsVisit(const Graph& g,
    64	                     int id,
    65	                     std::vector<int> ancestors,
    66	                     std::set<int>& done,
    67	                     std::vector<int>& out) {
    68	    if (done.count(id)) return;
    69	
    70	    // guard against re-entering a node already on the current path
    71	    for (std::size_t i = 0; i < ancestors.size(); ++i) {
    72	        if (ancestors[i] == id) return;
    73	    }
    74	    ancestors.push_back(id);
    75	
    76	    const std::vector<int>& nb = g.neighbors(id);
    77	    for (std::size_t i = 0; i < nb.size(); ++i) {
    78	        dfsVisit(g, nb[i], ancestors, done, out);
    79	    }
    80	
    81	    done.insert(id);
    82	    out.push_back(id);
    83	}
    84	
    85	std::vector<int> topoSortDfsRecursive(const Graph& g) {
    86	    std::vector<int> out;
    87	    std::set<int> done;
    88	    std::vector<int> ids = g.ids();
    89	    for (std::size_t i = 0; i < ids.size(); ++i) {
    90	        dfsVisit(g, ids[i], std::vector<int>(), done, out);
    91	    }
    92	    std::reverse(out.begin(), out.end());
    93	    return out;
    94	}
    95	
    96	static bool cycleFrom(const Graph& g, int id, std::map<int, char> color) {
    97	    color[id] = 'g';
    98	    const std::vector<int>& nb = g.neighbors(id);
    99	    for (std::size_t i = 0; i < nb.size(); ++i) {
   100	        int to = nb[i];
   101	        if (to == id) continue;
   102	        auto it = color.find(to);
   103	        if (it != color.end() && it->second == 'g') return true;
   104	        if (cycleFrom(g, to, color)) return true;
   105	    }
   106	    color[id] = 'b';
   107	    return false;
   108	}
   109	
   110	bool hasCycle(const Graph& g) {
   111	    std::map<int, char> color;
   112	    std::vector<int> ids = g.ids();
   113	    for (std::size_t i = 0; i < ids.size(); ++i) {
   114	        if (cycleFrom(g, ids[i], color)) return true;
   115	    }
   116	    return false;
   117	}
   118	
   119	}  // namespace badgraph

