     8	int lcaNaive(const Graph& g, int a, int b) {
     9	    Node* x = g.node(a);
    10	    Node* y = g.node(b);
    11	    if (x == nullptr || y == nullptr) return -1;
    12	
    13	    std::vector<int> pathA;
    14	    while (x != nullptr) {
    15	        pathA.push_back(x->id);
    16	        x = x->parent;
    17	    }
    18	
    19	    while (y != nullptr) {
    20	        for (std::size_t i = 0; i < pathA.size(); ++i) {
    21	            if (pathA[i] == y->id) return y->id;
    22	        }
    23	        y = y->parent;
    24	    }
    25	    return -1;
    26	}
    27	
    28	double subtreeSum(const Graph& g, int root) {
    29	    Node* n = g.node(root);
    30	    if (n == nullptr) return 0.0;
    31	
    32	    double sum = n->weight;
    33	    const std::vector<int>& kids = g.neighbors(root);
    34	    for (std::size_t i = 0; i < kids.size(); ++i) {
    35	        Node* c = g.node(kids[i]);
    36	        if (c == nullptr) continue;
    37	        sum += subtreeSum(g, c->id);
    38	    }
    39	    return sum;
    40	}
    41	
    42	std::vector<double> subtreeSumAll(const Graph& g) {
    43	    std::vector<double> out;
    44	    std::vector<int> ids = g.ids();
    45	    for (std::size_t i = 0; i < ids.size(); ++i) {
    46	        out.push_back(subtreeSum(g, ids[i]));
    47	    }
    48	    return out;
    49	}
