    51	std::vector<double> longestPathDag(const Graph& g, const std::vector<int>& order) {
    52	    std::map<int, double> dist;
    53	    for (const auto& kv : g.nodeMap()) {
    54	        dist[kv.first] = kv.second->weight;
    55	    }
    56	
    57	    for (std::size_t i = 0; i < order.size(); ++i) {
    58	        int id = order[i];
    59	        std::vector<int> nb = g.neighbors(id);
    60	        for (std::size_t j = 0; j < nb.size(); ++j) {
    61	            int to = nb[j];
    62	            Node* tn = g.node(to);
    63	            if (tn == nullptr) continue;
    64	            double cand = dist[id] + tn->weight;
    65	            if (cand > dist[to]) {
    66	                dist[to] = cand;
    67	            }
    68	        }
    69	    }
    70	
    71	    std::vector<double> out;
    72	    for (const auto& kv : g.nodeMap()) {
    73	        out.push_back(dist[kv.first]);
    74	    }
    75	    return out;
    76	}
    77	
    78	double criticalPath(const Graph& g) {
    79	    std::vector<int> order = topoSortKahnSlow(g);
    80	    std::vector<double> dist = longestPathDag(g, order);
    81	    double best = 0.0;
    82	    for (std::size_t i = 0; i < dist.size(); ++i) {
    83	        if (dist[i] > best) best = dist[i];
    84	    }
    85	    return best;
    86	}
