    88	std::vector<int> bfsLevels(const Graph& g, int root) {
    89	    std::map<int, int> level;
    90	    std::vector<int> frontier;
    91	    frontier.push_back(root);
    92	    level[root] = 0;
    93	
    94	    while (!frontier.empty()) {
    95	        int id = frontier.front();
    96	        frontier.erase(frontier.begin());
    97	
    98	        std::vector<int> nb = g.neighbors(id);
    99	        for (std::size_t i = 0; i < nb.size(); ++i) {
   100	            int to = nb[i];
   101	            if (level.count(to) == 0) {
   102	                level[to] = level[id] + 1;
   103	                frontier.push_back(to);
   104	            }
   105	        }
   106	    }
   107	
   108	    std::vector<int> out;
   109	    for (const auto& kv : g.nodeMap()) {
   110	        if (level.count(kv.first)) {
   111	            out.push_back(level[kv.first]);
   112	        } else {
   113	            out.push_back(-1);
   114	        }
   115	    }
   116	    return out;
   117	}
