   119	// Flatten the adjacency map into CSR form and return the per-node out-degree.
   120	std::vector<int> buildCsrAndCount(const Graph& g) {
   121	    int n = (int)g.size();
   122	    if (n <= 0) return std::vector<int>();
   123	
   124	    int* rowStart = new int[n];
   125	    int* degree = new int[n];
   126	
   127	    int i = 0;
   128	    for (const auto& kv : g.adjacency()) {
   129	        degree[i] = (int)kv.second.size();
   130	        ++i;
   131	    }
   132	
   133	    rowStart[0] = 0;
   134	    for (int k = 1; k <= n; ++k) {
   135	        rowStart[k] = rowStart[k - 1] + degree[k - 1];
   136	    }
   137	
   138	    int total = rowStart[n];
   139	    int* colIndex = new int[total > 0 ? total : 1];
   140	
   141	    i = 0;
   142	    int w = 0;
   143	    for (const auto& kv : g.adjacency()) {
   144	        for (std::size_t j = 0; j < kv.second.size(); ++j) {
   145	            colIndex[w++] = kv.second[j];
   146	        }
   147	        ++i;
   148	    }
   149	
   150	    std::vector<int> out;
   151	    for (int k = 0; k < n; ++k) out.push_back(degree[k]);
   152	
   153	    delete[] rowStart;
   154	    delete[] degree;
   155	    return out;
   156	}
