   158	static std::string upperFirst(std::string s) {
   159	    if (!s.empty() && s[0] >= 'a' && s[0] <= 'z') s[0] = (char)(s[0] - 32);
   160	    return s;
   161	}
   162	
   163	static bool labelMatches(std::string label, std::string needle) {
   164	    return label.find(needle) != std::string::npos;
   165	}
   166	
   167	std::string describeHot(const Graph& g, int limit) {
   168	    std::string report = "";
   169	    int count = 0;
   170	    for (const auto& kv : g.nodeMap()) {
   171	        if (count >= limit) break;
   172	        Node* n = kv.second;
   173	        if (!labelMatches(n->label, "node_")) continue;
   174	
   175	        std::string line = upperFirst(n->label);
   176	        line = line + " d=" + std::to_string(n->depth);
   177	        line = line + " w=" + std::to_string((long long)(n->weight * 100));
   178	        line = line + " k=" + std::to_string((long long)n->children.size());
   179	        for (std::size_t t = 0; t < n->tags.size(); ++t) {
   180	            line = line + ":" + std::to_string(n->tags[t]);
   181	        }
   182	        report = report + line + "\n";
   183	        ++count;
   184	    }
   185	    return report;
   186	}
