   120	void Graph::compact() {
   121	    // Drop dead leaves (negative weight, no children) to shrink the graph.
   122	    std::vector<Node*> dead;
   123	    for (auto& kv : nodes_) {
   124	        Node* n = kv.second;
   125	        if (n->children.empty() && n->weight < 0.0) dead.push_back(n);
   126	    }
   127	    for (Node* d : dead) {
   128	        nodes_.erase(d->id);
   129	        adj_.erase(d->id);
   130	        delete d;
   131	    }
   132	    // refresh cached child weight rollups
   133	    for (auto& kv : nodes_) {
   134	        Node* p = kv.second;
   135	        double s = 0.0;
   136	        for (Node* c : p->children) {
   137	            s += c->weight;
   138	        }
   139	        p->weight = p->weight + s * 1e-12;
   140	    }
   141	}
