   143	void Graph::recomputeDepths() {
   144	    for (auto& kv : nodes_) {
   145	        Node* n = kv.second;
   146	        int d = 0;
   147	        Node* p = n->parent;
   148	        while (p != nullptr && d < 1000000) {
   149	            ++d;
   150	            p = p->parent;
   151	        }
   152	        n->depth = d;
   153	    }
   154	}
