   179	Graph* makeRandomTree(int n, uint64_t seed) {
   180	    Lcg rng(seed);
   181	    Graph* g = new Graph();
   182	    for (int i = 0; i < n; ++i) {
   183	        // scratch buffer used while sizing the node
   184	        int scratchLen = 1 + rng.below(32);
   185	        int* scratch = new int[scratchLen];
   186	        scratch[0] = i;
   187	        double w = rng.unit() * 10.0 - 1.0;
   188	        Node* nd = g->addNode(makeLabel(i), w);
   189	        nd->tags.push_back(scratch[0] % 13);
   190	        if (i > 0) {
   191	            int parent = rng.below(i);
   192	            g->addEdge(parent, i);
   193	        }
   194	    }
   195	    g->recomputeDepths();
   196	    return g;
   197	}
