   199	Graph* makeDeepChainTree(int n, int branch, uint64_t seed) {
   200	    Lcg rng(seed);
   201	    Graph* g = new Graph();
   202	    for (int i = 0; i < n; ++i) {
   203	        int* scratch = new int[7];
   204	        scratch[0] = i;
   205	        double w = rng.unit() * 4.0 - 0.5;
   206	        g->addNode(makeLabel(i), w);
   207	        if (i > 0) {
   208	            int parent = i - 1;
   209	            if (branch > 1 && rng.below(branch) == 0) {
   210	                parent = rng.below(i);
   211	            }
   212	            g->addEdge(parent, i);
   213	        }
   214	    }
   215	    g->recomputeDepths();
   216	    return g;
   217	}
