   219	Graph* makeRandomDag(int n, int extraEdges, uint64_t seed) {
   220	    Lcg rng(seed);
   221	    Graph* g = makeRandomTree(n, seed ^ 0x9e3779b9ULL);
   222	    for (int e = 0; e < extraEdges; ++e) {
   223	        int a = rng.below(n);
   224	        int b = rng.below(n);
   225	        if (a == b) continue;
   226	        if (a > b) { int t = a; a = b; b = t; }
   227	        g->addEdge(a, b);
   228	    }
   229	    return g;
   230	}
