   241	uint64_t checksum(const std::vector<int>& v) {
   242	    uint64_t h = 1469598103934665603ULL;
   243	    for (int x : v) h = mixIn(h, (uint64_t)(uint32_t)x);
   244	    return h;
   245	}
   246	
   247	uint64_t checksum(const std::vector<double>& v) {
   248	    uint64_t h = 1469598103934665603ULL;
   249	    for (double d : v) {
   250	        // quantize so tiny FP reassociation differences do not flip the hash
   251	        long long q = (long long)(d * 1000.0 + (d < 0 ? -0.5 : 0.5));
   252	        h = mixIn(h, (uint64_t)q);
   253	    }
   254	    return h;
   255	}
