   263	bool isValidTopoOrder(const Graph& g, const std::vector<int>& order) {
   264	    if (order.size() != g.size()) return false;
   265	    std::map<int, int> pos;
   266	    for (std::size_t i = 0; i < order.size(); ++i) {
   267	        if (pos.count(order[i])) return false;  // duplicate
   268	        pos[order[i]] = (int)i;
   269	    }
   270	    for (const auto& kv : g.adjacency()) {
   271	        auto pf = pos.find(kv.first);
   272	        if (pf == pos.end()) return false;
   273	        for (int to : kv.second) {
   274	            auto pt = pos.find(to);
   275	            if (pt == pos.end()) return false;
   276	            if (pf->second >= pt->second) return false;
   277	        }
   278	    }
   279	    return true;
   280	}
