     1	// Benchmark driver for badgraph.
     2	//
     3	//   ./bin/bench                 run everything at scale 1.0
     4	//   ./bin/bench --scale 0.25    smaller workload (fast smoke)
     5	//   ./bin/bench --reps 5        repetitions per benchmark (the fastest wins)
     6	//   ./bin/bench --only topo     run benchmarks whose name contains "topo"
     7	//   ./bin/bench --json out.json write machine readable results
     8	//
     9	// Each benchmark is timed `reps` times and the *minimum* is reported, which is
    10	// far more stable than a single sample.  Each one also prints a checksum over
    11	// its real output; an optimization is only valid if the checksum is unchanged.
    12	#include "badgraph.hpp"
    13	
    14	#include <chrono>
    15	#include <cstdio>
    16	#include <cstdlib>
    17	#include <cstring>
    18	#include <string>
    19	#include <vector>
    20	
    21	using namespace badgraph;
    22	
    23	namespace {
    24	
    25	struct Result {
    26	    std::string name;
    27	    double ms = 0.0;
    28	    uint64_t sum = 0;
    29	    std::string note;
    30	};
    31	
    32	std::vector<Result> g_results;
    33	const char* g_only = nullptr;
    34	int g_reps = 3;
    35	
    36	double nowMs() {
    37	    using clock = std::chrono::steady_clock;
    38	    static clock::time_point origin = clock::now();
    39	    return std::chrono::duration<double, std::milli>(clock::now() - origin).count();
    40	}
    41	
    42	int scaled(int base, double s) {
    43	    int v = (int)(base * s);
    44	    return v < 4 ? 4 : v;
    45	}
    46	
    47	bool wanted(const std::string& name) {
    48	    if (g_only == nullptr) return true;
    49	    return name.find(g_only) != std::string::npos;
    50	}
    51	
    52	// fn(note) runs one iteration and returns a checksum of its output.
    53	template <class F>
    54	void bench(const char* name, F fn) {
    55	    if (!wanted(name)) return;
    56	
    57	    double best = -1.0;
    58	    uint64_t sum = 0;
    59	    std::string note;
    60	    bool stable = true;
    61	
    62	    for (int r = 0; r < g_reps; ++r) {
    63	        std::string thisNote;
    64	        double t0 = nowMs();
    65	        uint64_t s = fn(thisNote);
    66	        double dt = nowMs() - t0;
    67	        if (r == 0) {
    68	            sum = s;
    69	            note = thisNote;
    70	        } else if (s != sum) {
    71	            stable = false;
    72	        }
    73	        if (best < 0.0 || dt < best) best = dt;
    74	    }
    75	    if (!stable) note += " NONDETERMINISTIC";
    76	
    77	    Result res;
    78	    res.name = name;
    79	    res.ms = best;
    80	    res.sum = sum;
    81	    res.note = note;
    82	    g_results.push_back(res);
    83	    std::printf("  %-22s %10.2f ms   sum=0x%016llx  %s\n",
    84	                name, best, (unsigned long long)sum, note.c_str());
    85	    std::fflush(stdout);
    86	}
    87	
    88	}  // namespace
