    40	static std::vector<int> refTopo(const Graph& g) {
    41	    std::map<int, int> deg = refIndegrees(g);
    42	    std::deque<int> q;
    43	    for (const auto& kv : deg)
    44	        if (kv.second == 0) q.push_back(kv.first);
    45	    std::vector<int> out;
