    60	    q.push_back(root);
    61	    while (!q.empty()) {
    62	        int id = q.front();
    63	        q.pop_front();
    64	        for (int to : g.neighbors(id)) {
    65	            if (!d.count(to)) {
    66	                d[to] = d[id] + 1;
    67	                q.push_back(to);
    68	            }
    69	        }
    70	    }
