    75	static int refLca(const Graph& g, int root, int a, int b) {
    76	    std::map<int, int> up;
    77	    std::deque<int> q;
    78	    up[root] = -1;
    79	    q.push_back(root);
    80	    while (!q.empty()) {
    81	        int id = q.front();
    82	        q.pop_front();
    83	        for (int to : g.neighbors(id)) {
    84	            if (!up.count(to)) {
    85	                up[to] = id;
    86	                q.push_back(to);
    87	            }
    88	        }
    89	    }
    90	    std::set<int> anc;
    91	    for (int x = a; x != -1; x = up.count(x) ? up[x] : -1) {
    92	        anc.insert(x);
    93	        if (x == root) break;
    94	    }
    95	    for (int y = b; y != -1; y = up.count(y) ? up[y] : -1) {
    96	        if (anc.count(y)) return y;
    97	        if (y == root) break;
    98	    }
    99	    return -1;
