   102	static double refSubtreeSum(const Graph& g, int root) {
   103	    double total = 0.0;
   104	    std::vector<int> stack;
   105	    std::set<int> seen;
   106	    stack.push_back(root);
   107	    while (!stack.empty()) {
   108	        int id = stack.back();
   109	        stack.pop_back();
   110	        if (seen.count(id)) continue;
   111	        seen.insert(id);
   112	        Node* n = g.node(id);
   113	        if (n) total += n->weight;
   114	        for (int to : g.neighbors(id)) stack.push_back(to);
   115	    }
   116	    return total;
   117	}
