   119	static std::vector<double> refLongestPath(const Graph& g) {
   120	    std::vector<int> order = refTopo(g);
   121	    std::map<int, double> dist;
   122	    for (const auto& kv : g.nodeMap()) dist[kv.first] = kv.second->weight;
   123	    for (int id : order) {
   124	        for (int to : g.neighbors(id)) {
   125	            Node* tn = g.node(to);
   126	            if (!tn) continue;
   127	            double cand = dist[id] + tn->weight;
   128	            if (cand > dist[to]) dist[to] = cand;
   129	        }
   130	    }
   131	    std::vector<double> out;
   132	    for (const auto& kv : g.nodeMap()) out.push_back(dist[kv.first]);
   133	    return out;
   134	}
