    10	import sys
    11	
    12	# Regressions below this are treated as measurement noise, not a real change.
    13	TOLERANCE = 1.10
    14	
    15	
    16	def load(path):
    17	    with open(path) as f:
    18	        data = json.load(f)
    19	    return data, {r["name"]: r for r in data["results"]}
    20	
    21	
    22	def main():
    23	    if len(sys.argv) != 3:
    24	        print(__doc__)
    25	        return 2
    26	    base_raw, base = load(sys.argv[1])
    27	    cur_raw, cur = load(sys.argv[2])
    28	
    29	    if abs(base_raw.get("scale", 1) - cur_raw.get("scale", 1)) > 1e-9:
    30	        print("WARNING: scale differs (%s vs %s); timings are not comparable"
    31	              % (base_raw.get("scale"), cur_raw.get("scale")))
    32	
    33	    print("%-22s %12s %12s %9s  %s" % ("benchmark", "baseline", "current", "speedup", "checksum"))
    34	    print("-" * 74)
    35	
    36	    bad = 0
    37	    for name in base:
    38	        b = base[name]
    39	        c = cur.get(name)
    40	        if c is None:
    41	            print("%-22s %12.2f %12s %9s  MISSING" % (name, b["ms"], "-", "-"))
    42	            bad += 1
    43	            continue
    44	        speed = b["ms"] / c["ms"] if c["ms"] > 0 else float("inf")
    45	        ok = b["checksum"] == c["checksum"]
    46	        if not ok:
    47	            bad += 1
    48	        print("%-22s %12.2f %12.2f %8.2fx  %s"
    49	              % (name, b["ms"], c["ms"], speed, "ok" if ok else "CHANGED <-- INVALID"))
    50	
    51	    for name in cur:
    52	        if name not in base:
    53	            print("%-22s %12s %12.2f %9s  (new)" % (name, "-", cur[name]["ms"], "-"))
    54	
    55	    bt, ct = base_raw["total_ms"], cur_raw["total_ms"]
    56	    print("-" * 74)
    57	    print("%-22s %12.2f %12.2f %8.2fx" % ("TOTAL", bt, ct, bt / ct if ct > 0 else float("inf")))
    58	
    59	    if bad:
