// Node ids come from a counter that starts at zero and only increments, and
// Graph::addEdge refuses an endpoint that is not a live node, so every id in
// nodeMap() or in an adjacency list lies in [0, maxNodeId(g)].
int maxNodeId(const Graph& g) {
    const std::map<int, Node*>& nm = g.nodeMap();
    return nm.empty() ? -1 : nm.rbegin()->first;
}

// Membership over a nonempty set of node ids in constant or logarithmic time.
// A bitmap is used when the ids span a range comparable to the set size (the
// rooted-chain case), a sorted copy otherwise, so the scratch space stays
// proportional to the number of ids rather than to the id range.
class IdSet {
public:
    explicit IdSet(const std::vector<int>& ids) : lo_(ids.front()), hi_(ids.front()) {
        for (std::size_t i = 1; i < ids.size(); ++i) {
            if (ids[i] < lo_) lo_ = ids[i];
            if (ids[i] > hi_) hi_ = ids[i];
        }
        const long long span = (long long)hi_ - (long long)lo_ + 1;
        if (span <= 4 * (long long)ids.size() + 64) {
            mark_.assign((std::size_t)span, 0);
            for (std::size_t i = 0; i < ids.size(); ++i) mark_[(std::size_t)(ids[i] - lo_)] = 1;
        } else {
            sorted_ = ids;
            std::sort(sorted_.begin(), sorted_.end());
        }
    }

    bool contains(int id) const {
        if (id < lo_ || id > hi_) return false;
        if (!mark_.empty()) return mark_[(std::size_t)(id - lo_)] != 0;
        return std::binary_search(sorted_.begin(), sorted_.end(), id);
    }

private:
    int lo_;
}

