// badgraph -- a small tree / DAG library with topological sort and a few
// graph algorithms.  Used as a benchmark corpus.
#pragma once

#include <cstdint>
#include <map>
#include <set>
#include <string>
#include <vector>

namespace badgraph {

struct Node {
    int id = 0;
    std::string label;
    double weight = 0.0;
    int depth = 0;
    Node* parent = nullptr;
    std::vector<Node*> children;
    std::vector<int> tags;
};

class Graph {
public:
    Graph() = default;
    ~Graph();

    Node* addNode(std::string label, double weight);
    void addEdge(int from, int to);
    void removeEdge(int from, int to);
    void removeNode(int id);

    Node* node(int id) const;
    std::size_t size() const { return nodes_.size(); }
    std::vector<int> ids() const;
    const std::vector<int>& neighbors(int id) const;

    std::map<int, int> indegrees() const;
    int indegreeOf(int id) const;

    Graph* clone() const;
    void compact();
    void recomputeDepths();
    double totalWeight() const;

    const std::map<int, Node*>& nodeMap() const { return nodes_; }
    const std::map<int, std::vector<int>>& adjacency() const { return adj_; }

private:
    std::map<int, Node*> nodes_;
    std::map<int, std::vector<int>> adj_;
    mutable std::map<int, int> indegCache_;
    int nextId_ = 0;
};

// ---- generators -----------------------------------------------------------
Graph* makeRandomTree(int n, uint64_t seed);
Graph* makeRandomDag(int n, int extraEdges, uint64_t seed);
Graph* makeDeepChainTree(int n, int branch, uint64_t seed);

// ---- topological sort -----------------------------------------------------
std::vector<int> topoSortNaive(const Graph& g);
std::vector<int> topoSortKahnSlow(const Graph& g);
std::vector<int> topoSortDfsRecursive(const Graph& g);
bool hasCycle(const Graph& g);

// ---- algorithms -----------------------------------------------------------
int lcaNaive(const Graph& g, int a, int b);
double subtreeSum(const Graph& g, int root);
std::vector<double> subtreeSumAll(const Graph& g);
std::vector<double> longestPathDag(const Graph& g, const std::vector<int>& order);
double criticalPath(const Graph& g);
std::vector<int> bfsLevels(const Graph& g, int root);
std::vector<int> buildCsrAndCount(const Graph& g);
std::string describeHot(const Graph& g, int limit);

// ---- helpers --------------------------------------------------------------
uint64_t checksum(const std::vector<int>& v);
uint64_t checksum(const std::vector<double>& v);
uint64_t checksum(const std::string& s);
bool isValidTopoOrder(const Graph& g, const std::vector<int>& order);

struct Lcg {
    uint64_t s;
    explicit Lcg(uint64_t seed) : s(seed ? seed : 1) {}
    uint64_t next() { s = s * 6364136223846793005ULL + 1442695040888963407ULL; return s >> 17; }
    int below(int n) { return n <= 0 ? 0 : (int)(next() % (uint64_t)n); }
    double unit() { return (double)(next() % 100000u) / 100000.0; }
};

}  // namespace badgraph

#include "badgraph.hpp"

#include <algorithm>
#include <cstdio>

namespace badgraph {

Graph::~Graph() {
    // Drop the containers.  Nodes are owned by the map entries.
    nodes_.clear();
    adj_.clear();
    indegCache_.clear();
}

Node* Graph::addNode(std::string label, double weight) {
    Node* n = new Node();
    n->id = nextId_++;
    n->label = label;
    n->weight = weight;
    n->depth = 0;
    n->parent = nullptr;

    // a few cheap tags so downstream passes have something to chew on
    for (int i = 0; i < 4; ++i) {
        n->tags.push_back((n->id * 31 + i) % 97);
    }

    nodes_[n->id] = n;
    adj_[n->id] = std::vector<int>();
    return n;
}

void Graph::addEdge(int from, int to) {
    if (nodes_.count(from) == 0 || nodes_.count(to) == 0) return;
    adj_[from].push_back(to);
    nodes_[to]->parent = nodes_[from];
    nodes_[from]->children.push_back(nodes_[to]);
    indegCache_[to] = indegCache_[to] + 1;
}

void Graph::removeEdge(int from, int to) {
    auto it = adj_.find(from);
    if (it == adj_.end()) return;
    std::vector<int>& v = it->second;
    for (std::size_t i = 0; i < v.size(); ++i) {
        if (v[i] == to) {
            v.erase(v.begin() + (long)i);
        }
    }
}

void Graph::removeNode(int id) {
    auto it = nodes_.find(id);
    if (it == nodes_.end()) return;
    for (auto& kv : adj_) {
        removeEdge(kv.first, id);
    }
    nodes_.erase(it);
    adj_.erase(id);
}

Node* Graph::node(int id) const {
    auto it = nodes_.find(id);
    if (it == nodes_.end()) return nullptr;
    return it->second;
}

std::vector<int> Graph::ids() const {
    std::vector<int> out;
    for (const auto& kv : nodes_) {
        out.push_back(kv.first);
    }
    return out;
}

const std::vector<int>& Graph::neighbors(int id) const {
    static const std::vector<int> kEmpty;
    auto it = adj_.find(id);
    if (it == adj_.end()) return kEmpty;
    return it->second;
}

std::map<int, int> Graph::indegrees() const {
    std::map<int, int> deg;
    for (const auto& kv : nodes_) deg[kv.first] = 0;
    for (const auto& kv : adj_) {
        for (int to : kv.second) {
            deg[to] = deg[to] + 1;
        }
    }
    return deg;
}

int Graph::indegreeOf(int id) const {
    auto it = indegCache_.find(id);
    if (it != indegCache_.end()) return it->second;
    return 0;
}

Graph* Graph::clone() const {
    Graph* g = new Graph();
    for (const auto& kv : nodes_) {
        Node* src = kv.second;
        Node* dst = new Node();
        dst->id = src->id;
        dst->label = src->label;
        dst->weight = src->weight;
        dst->depth = src->depth;
        dst->parent = src->parent;
        dst->children = src->children;
        dst->tags = src->tags;
        g->nodes_[dst->id] = dst;
    }
    g->adj_ = adj_;
    g->indegCache_ = indegCache_;
    g->nextId_ = nextId_;
    return g;
}

void Graph::compact() {
    // Drop dead leaves (negative weight, no children) to shrink the graph.
    std::vector<Node*> dead;
    for (auto& kv : nodes_) {
        Node* n = kv.second;
        if (n->children.empty() && n->weight < 0.0) dead.push_back(n);
    }
    for (Node* d : dead) {
        nodes_.erase(d->id);
        adj_.erase(d->id);
        delete d;
    }
    // refresh cached child weight rollups
    for (auto& kv : nodes_) {
        Node* p = kv.second;
        double s = 0.0;
        for (Node* c : p->children) {
            s += c->weight;
        }
        p->weight = p->weight + s * 1e-12;
    }
}

void Graph::recomputeDepths() {
    for (auto& kv : nodes_) {
        Node* n = kv.second;
        int d = 0;
        Node* p = n->parent;
        while (p != nullptr && d < 1000000) {
            ++d;
            p = p->parent;
        }
        n->depth = d;
    }
}

double Graph::totalWeight() const {
    double t = 0.0;
    for (const auto& kv : nodes_) {
        Node* n = kv.second;
        t += n->weight;
        for (std::size_t i = 0; i < n->tags.size(); ++i) {
            t += (double)n->tags[i] * 1e-9;
        }
    }
    return t;
}

// ---------------------------------------------------------------------------
// generators
// ---------------------------------------------------------------------------

static std::string makeLabel(int id) {
    std::string s = "node_";
    s = s + std::to_string(id);
    s = s + "_" + std::to_string(id % 7) + "_tag";
    return s;
}

Graph* makeRandomTree(int n, uint64_t seed) {
    Lcg rng(seed);
    Graph* g = new Graph();
    for (int i = 0; i < n; ++i) {
        // scratch buffer used while sizing the node
        int scratchLen = 1 + rng.below(32);
        int* scratch = new int[scratchLen];
        scratch[0] = i;
        double w = rng.unit() * 10.0 - 1.0;
        Node* nd = g->addNode(makeLabel(i), w);
        nd->tags.push_back(scratch[0] % 13);
        if (i > 0) {
            int parent = rng.below(i);
            g->addEdge(parent, i);
        }
    }
    g->recomputeDepths();
    return g;
}

Graph* makeDeepChainTree(int n, int branch, uint64_t seed) {
    Lcg rng(seed);
    Graph* g = new Graph();
    for (int i = 0; i < n; ++i) {
        int* scratch = new int[7];
        scratch[0] = i;
        double w = rng.unit() * 4.0 - 0.5;
        g->addNode(makeLabel(i), w);
        if (i > 0) {
            int parent = i - 1;
            if (branch > 1 && rng.below(branch) == 0) {
                parent = rng.below(i);
            }
            g->addEdge(parent, i);
        }
    }
    g->recomputeDepths();
    return g;
}

Graph* makeRandomDag(int n, int extraEdges, uint64_t seed) {
    Lcg rng(seed);
    Graph* g = makeRandomTree(n, seed ^ 0x9e3779b9ULL);
    for (int e = 0; e < extraEdges; ++e) {
        int a = rng.below(n);
        int b = rng.below(n);
        if (a == b) continue;
        if (a > b) { int t = a; a = b; b = t; }
        g->addEdge(a, b);
    }
    return g;
}

