std::string describeHot(const Graph& g, int limit) {
    std::string report = "";
    int count = 0;
    for (const auto& kv : g.nodeMap()) {
        if (count >= limit) break;
        Node* n = kv.second;
        if (!labelMatches(n->label, "node_")) continue;
        std::string line = upperFirst(n->label);
        line = line + " d=" + std::to_string(n->depth);
        line = line + " w=" + std::to_string((long long)(n->weight * 100));
        line = line + " k=" + std::to_string((long long)n->children.size());
        for (std::size_t t = 0; t < n->tags.size(); ++t) {
            line = line + ":" + std::to_string(n->tags[t]);
        }
        report = report + line + "\n";
        ++count;
    }
    return report;
}

