// Topology-only checks (safe on cyclic graphs / self-parents).
static void checkTopo(const Graph& g, const char* ctx) {
    cmpVec("topoSortNaive", ctx, ref::topoSortNaive(g), topoSortNaive(g));
    cmpVec("topoSortKahnSlow", ctx, ref::topoSortKahnSlow(g), topoSortKahnSlow(g));
    cmpVec("topoSortDfsRecursive", ctx, ref::topoSortDfsRecursive(g), topoSortDfsRecursive(g));
    for (int root : {0, 1, 7, -1, 999999}) {
        cmpVec("bfsLevels", ctx, ref::bfsLevels(g, root), bfsLevels(g, root));
    }
    for (int lim : {0, 1, 3, 100000}) {
        cmpStr("describeHot", ctx, ref::describeHot(g, lim), describeHot(g, lim));
    }
}

